       color: var(--text);
       background:
         radial-gradient(circle at top, #eaf2ff 0%, transparent 34%),
         linear-gradient(180deg, #f7faff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .page-shell {
       width: min(100%, 640px);
