       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border: 1px solid var(--border);
       border-radius: 14px;
       background: #fbfdff;
       transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
       cursor: pointer;
