   <main class="page-shell">
     <section class="card" aria-labelledby="preferences-title">
       <h1 id="preferences-title">Notification preferences</h1>
       <p class="subtitle">Choose the single channel you'd like us to use.</p>

       <form id="notification-form">
         <div class="form-field">
           <p class="question">How do you prefer to receive notifications?</p>
           <div class="options" role="radiogroup" aria-labelledby="preferences-title">
             <label class="option">
               <input type="radio" name="notificationPreference" value="Email" required />
               <span>Email</span>
             </label>
             <label class="option">
               <input type="radio" name="notificationPreference" value="SMS" />
               <span>SMS</span>
             </label>
             <label class="option">
               <input type="radio" name="notificationPreference" value="Push Notifications" />
               <span>Push Notifications</span>
             </label>
           </div>
         </div>

         <div class="form-actions">
           <button type="submit">Submit</button>
         </div>
         <div class="message" id="form-message" aria-live="polite"></div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('notification-form');
     const message = document.getElementById('form-message');

     form.addEventListener('submit', (event) => {
